import React, { useState } from "react";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { tomorrow } from "react-syntax-highlighter/dist/esm/styles/prism";


import { ExtractSnippet } from "./ExtractSnippet";

export default function CodePreview({
  demo,
  source,
  snippetName,
  language = "jsx",
}) {
  const [expanded, setExpanded] = useState(false);
  const [copied, setCopied] = useState(false);

  const code = snippetName && source ? ExtractSnippet(source, snippetName) : source || "";

  // Dedent helper: remove a leading newline and common indentation, preserve relative indents
  const dedentBlock = (text) => {
    if (!text) return "";
    const normalized = text.replace(/\r\n?|\u2028|\u2029/g, "\n").replace(/^\uFEFF/, "");
    const withoutLeadingNewline = normalized.replace(/^\n/, "");
    const lines = withoutLeadingNewline.split("\n");
    let minIndent = Infinity;
    for (const line of lines) {
      if (line.trim().length === 0) continue;
      const m = line.match(/^[\t ]*/);
      const count = m ? m[0].length : 0;
      if (count < minIndent) minIndent = count;
    }
    if (!isFinite(minIndent)) minIndent = 0;
    let out = lines.map((l) => (l.trim().length === 0 ? l : l.slice(minIndent)));
    if (out.length > 0) out[0] = out[0].replace(/^\s+/, "");
    return out.join("\n").trimEnd();
  };

  // Helper to extract JSX from return(<...>) for collapsed preview
  // Prefer the component's JSX return over cleanup returns like `return () => {}`
  const extractReturnJSX = (code) => {
    if (!code) return "";
    const normalized = code.replace(/\r\n?|\u2028|\u2029/g, "\n");
    // Find a `return (` where the next non-space char after '(' is '<'
    const re = /return\s*\(\s*</g;
    const match = re.exec(normalized);
    if (!match) {
      // fallback: previous behavior
      const anyReturn = normalized.match(/return\s*\(/);
      if (!anyReturn) return "";
      const st = anyReturn.index + anyReturn[0].length;
      return dedentBlock(normalized.slice(st));
    }
    const startIndex = match.index + match[0].length - 1; // position at '<'
    // Walk parentheses starting from the '(' just before '<'
    // Find the '(' corresponding to this match
    const openIndex = normalized.lastIndexOf('(', startIndex);
    let parenCount = 1;
    let endIndex = startIndex + 1;
    for (let i = startIndex + 1; i < normalized.length; i++) {
      const ch = normalized[i];
      if (ch === '(') parenCount++;
      else if (ch === ')') parenCount--;
      if (parenCount === 0) { endIndex = i; break; }
    }
    const betweenParens = normalized.substring(openIndex + 1, endIndex);
    return dedentBlock(betweenParens);
  };

  // Decide how to build the code to display based on language
  const isJsx = (language || "jsx").toLowerCase() === "jsx";
  let displayCode;

  if (!isJsx) {
    // For non-JSX (e.g., less, css, json, text) show verbatim
    displayCode = dedentBlock(code || "");
  } else {
    const collapsedCode = extractReturnJSX(code);
    const fragmentMatch = collapsedCode.match(/^<>\s*([\s\S]*?)\s*<\/>\s*$/);
    const collapsedClean = fragmentMatch ? fragmentMatch[1].trim() : collapsedCode;
    displayCode = dedentBlock(expanded ? code : collapsedClean);
  }

  // Guarantee first line is flush-left (no stray leading tabs/spaces)
  const finalDisplayCode = (displayCode || "").replace(/^\s+/, "");

  const handleCopy = () => {
    navigator.clipboard.writeText(finalDisplayCode || "");
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="code-preview-container">
      {demo && <div className="demo bg-default bd pd16 mgb8 rds3">{demo}</div>}
      <div className="code-block" >
        <SyntaxHighlighter
          key={isJsx && expanded ? "expanded" : "collapsed"}
          language={language}
          style={tomorrow}
        >
          {finalDisplayCode || "// No code available"}
        </SyntaxHighlighter>
        <div className="code-actions fxb gp4 pdy2 pdx6">
          {demo && (
            <button onClick={() => setExpanded(!expanded)}>
              <i className="pi pi-code font-size14"></i>
            </button>
          )}
          <button onClick={handleCopy}>
            {copied ? (
              <i className="pi pi-check font-size13"></i>
            ) : (
              <i className="pi pi-copy font-size14"></i>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}